SELECT 'other_scoped_sp' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id <> 'SLONY') AS md5;
SELECT 'other_settings' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.setting_id)) FROM location_product_settings t WHERE t.location_id <> 'SLONY') AS md5;
SELECT 'other_suppliers' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_id)) FROM suppliers t WHERE t.supplier_id NOT IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA')) AS md5;
SELECT 'other_locations' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.location_id)) FROM locations t WHERE t.location_id <> 'SLONY') AS md5;

-- 0f. activity at SLONY (expect 0 / 0 / 0)
SELECT (SELECT count(*) FROM orders WHERE location_id = 'SLONY') AS orders,
       (SELECT count(*) FROM inventory_counts WHERE location_id = 'SLONY') AS counts,
       (SELECT count(*) FROM receipts WHERE location_id = 'SLONY') AS receipts;

-- =====================================================================================
-- STEP 1 — one transaction per call. Defined once as a function (payload sent once), called with
-- dry_run = true (raises 'DRY RUN OK …' → everything rolled back) and then false, then dropped.
-- =====================================================================================
CREATE OR REPLACE FUNCTION public.gdansk_rollout_step1(dry_run boolean) RETURNS text
LANGUAGE plpgsql AS $fn$
DECLARE
  n int;
  fp_before text[];
  fp_after text[];
  bad text;
BEGIN
  -- guards ------------------------------------------------------------------------------
  SELECT count(*) INTO n FROM information_schema.columns
   WHERE table_schema = 'public'
     AND ((table_name = 'locations' AND column_name = 'own_catalog')
       OR (table_name = 'supplier_products' AND column_name IN ('location_id', 'is_backup')));
  IF n <> 3 THEN RAISE EXCEPTION 'migration 0029 columns missing (%)', n; END IF;

  SELECT count(*) INTO n FROM locations
   WHERE location_id = 'SLONY' AND active = false AND own_catalog = false AND delivery_address IS NULL
     AND company_nip IS NULL AND city = 'Gdańsk';
  IF n <> 1 THEN RAISE EXCEPTION 'SLONY is not in the expected pre-rollout state'; END IF;

  SELECT count(*) INTO n FROM location_product_settings WHERE location_id = 'SLONY';
  IF n <> 115 THEN RAISE EXCEPTION 'SLONY settings: expected 115, found %', n; END IF;
  IF (SELECT md5(string_agg(s::text, '|' ORDER BY s.setting_id)) FROM location_product_settings s
       WHERE s.location_id = 'SLONY') <> '11ee78f0bec056bf308d9adbc2feb457' THEN
    RAISE EXCEPTION 'SLONY settings changed since the 2026-10-16 read — regenerate';
  END IF;

  IF EXISTS (SELECT 1 FROM orders WHERE location_id = 'SLONY')
     OR EXISTS (SELECT 1 FROM inventory_counts WHERE location_id = 'SLONY')
     OR EXISTS (SELECT 1 FROM receipts WHERE location_id = 'SLONY') THEN
    RAISE EXCEPTION 'SLONY already has orders / counts / receipts';
  END IF;

  IF EXISTS (SELECT 1 FROM suppliers WHERE supplier_id IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA')) THEN
    RAISE EXCEPTION 'a Gdańsk supplier already exists — step 1 was applied?';
  END IF;
  IF EXISTS (SELECT 1 FROM supplier_products WHERE location_id = 'SLONY' OR supplier_id IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA')) THEN
    RAISE EXCEPTION 'SLONY-scoped or Gdańsk catalog rows already exist';
  END IF;

  SELECT count(*) INTO n FROM supplier_products
   WHERE supplier_product_id IN ('SP_COCACOLA_P066', 'SP_COCACOLA_P067')
     AND units_per_purchase_unit = 24 AND case_unit IS NULL;
  IF n <> 2 THEN RAISE EXCEPTION 'SP_COCACOLA_P066/P067 not 24 per unit without case (%)', n; END IF;

  fp_before := ARRAY[(SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id IS NULL),
                     (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id <> 'SLONY'),
                     (SELECT md5(string_agg(t::text, '|' ORDER BY t.setting_id)) FROM location_product_settings t WHERE t.location_id <> 'SLONY'),
                     (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_id)) FROM suppliers t WHERE t.supplier_id NOT IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA')),
                     (SELECT md5(string_agg(t::text, '|' ORDER BY t.location_id)) FROM locations t WHERE t.location_id <> 'SLONY')];

  -- mapping (from sheet-mapping.csv) ----------------------------------------------------
  CREATE TEMP TABLE gda_map (
    sheet_row int, supplier_id text, product_id text, src_sp text, name text, pos int,
    is_backup boolean, pu text, upp numeric, price_null boolean, order_note text, extra text,
    cross_brand boolean, notes text
  ) ON COMMIT DROP;
  INSERT INTO gda_map (sheet_row, supplier_id, product_id, src_sp, name, pos, is_backup, pu, upp,
