    (5, 'SUP_KUCHNIE_GDA', 'P015', 'SP_KUCHNIE_KAT_P015', 'Ser na grilla 200g/12 Reha', 3, false, NULL, NULL, false, NULL, NULL),
    (6, 'SUP_KUCHNIE_GDA', 'P020', 'SP_KUCHNIE_KAT_P020', 'Falafel standard. bób/ciecierzyca mroż. 5kg', 4, false, NULL, NULL, false, NULL, 'arkusz karton 5 kg -> kg (x5)'),
