  -- 1. location -------------------------------------------------------------------------
  UPDATE locations SET
    delivery_address = 'Słony Spichlerz, ul. Chmielna 10',
    city = '80-748 Gdańsk',
    company_name = 'Pita Bros Gdańsk sp. z o.o.',
    company_address = 'ul. W. Laskonogiego 9, 02-496 Warszawa',
    company_nip = '5223329662',
    phone = '692 105 365',
    own_catalog = true,
    active = true,
    notes = 'rollout 2026-10-16 (gdansk-rollout): adres lokalu i telefon z COMPANY_ENTITIES.md, siedziba i NIP spółki z umowy ramowej Erste (Drive); katalog własny Gdańsk (own_catalog); E-MAIL LOKALU DO UZUPEŁNIENIA'
   WHERE location_id = 'SLONY';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'location update: %', n; END IF;

  -- 2. suppliers ------------------------------------------------------------------------
  INSERT INTO suppliers (supplier_id, supplier_name, email, ordering_method, delivery_days, cutoff_time,
                         minimum_order_value_pln, active, notes, nip, suggestion_alerts_enabled,
                         coverage_prompt_enabled)
  VALUES
    ('SUP_KUCHNIE_GDA', 'Kuchnie Świata Gdańsk', NULL, 'manual', NULL, NULL, NULL, true, 'gdansk-rollout 2026-10-16: dostawca miejski, katalog tylko dla SLONY (supplier_products.location_id); arkusz Marka ''Miasta poza Warszawą'', zakładka Gdańsk; kontakt, minimum i dni dostaw do potwierdzenia — Marek; NIP jak SUP_KUCHNIE (Kuchnie Świata S.A.); który oddział obsługuje Gdańsk - do potw.', '1180039859', true, false),
    ('SUP_SELGROS_GDA', 'Selgros Gdańsk', NULL, 'manual', NULL, NULL, NULL, true, 'gdansk-rollout 2026-10-16: dostawca miejski, katalog tylko dla SLONY (supplier_products.location_id); arkusz Marka ''Miasta poza Warszawą'', zakładka Gdańsk; e-mail z arkusza: horeca.gdansk@selgros.pl (niepotwierdzony, nie wpisany w pole e-mail — zamówienie ręczne); minimum i dni dostaw do potw.', NULL, true, false),
    ('SUP_COCACOLA_GDA', 'Coca-Cola Gdańsk', NULL, 'portal', NULL, NULL, NULL, true, 'gdansk-rollout 2026-10-16: dostawca miejski, katalog tylko dla SLONY (supplier_products.location_id); arkusz Marka ''Miasta poza Warszawą'', zakładka Gdańsk; zamawianie przez portal: https://cchbcshop.com/websitePL/pl/ (z arkusza; jak SUP_COCACOLA); konto / adres dostawy Gdańsk i minimum do potw.; NIP jak SUP_COCACOLA; szkło zwrotne — skrzynki do zwrotu kapitan wpisuje w komentarzu', '5242106963', true, false),
    ('SUP_WARSZAWA_GDA', 'Pago + Magazyn + Lemoniady (Gdańsk)', NULL, 'manual', NULL, NULL, 0.00, true, 'gdansk-rollout 2026-10-16: dostawca miejski, katalog tylko dla SLONY (supplier_products.location_id); arkusz Marka ''Miasta poza Warszawą'', zakładka Gdańsk; jedno zamówienie Gdańska z Warszawy — Pago (Lineage), Magazyn własny Mory, lemoniady Filber, nabiał Bukat; manager zbiera towar w Warszawie (Kopiuj listę) i oznacza jako zamówione; poza Transportem zbiorczym; minimum 0 — towar wewnętrzny; alerty sugestii wył. jak SUP_PAGO / SUP_WARSZAWA_KAT', NULL, false, false),
    ('SUP_BLUESERV_GDA', 'Blue Service Gdańsk', NULL, 'manual', NULL, NULL, NULL, true, 'gdansk-rollout 2026-10-16: dostawca miejski, katalog tylko dla SLONY (supplier_products.location_id); arkusz Marka ''Miasta poza Warszawą'', zakładka Gdańsk; lista jak warszawski Blue Service (+ biurowe z Magazynu); czy to ten sam Blue Service (NIP 1251685763, m.filipiuk@blueservice.com.pl) czy hurtownia lokalna — do potw.; kontakt i minimum do potw.', NULL, true, false);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 5 THEN RAISE EXCEPTION 'suppliers inserted: %', n; END IF;

  -- 3. scoped catalog rows (copies of the source rows with overrides; always active) -----
  INSERT INTO supplier_products (supplier_product_id, supplier_id, product_id, supplier_product_name,
         purchase_unit, units_per_purchase_unit, rounding_rule, price_estimate_pln, active, notes,
         order_note, unit_weight_kg, supplier_sku, warehouse_pickup, display_order,
         counts_toward_minimum, case_unit, units_per_case, location_id, is_backup)
  SELECT 'SP_' || substr(m.supplier_id, 5) || '_' || m.product_id, m.supplier_id, m.product_id, m.name,
         coalesce(m.pu, sp.purchase_unit), coalesce(m.upp, sp.units_per_purchase_unit), sp.rounding_rule,
         CASE WHEN m.price_null THEN NULL ELSE sp.price_estimate_pln END, true, m.notes,
         CASE WHEN m.order_note IS NOT NULL THEN m.order_note WHEN m.cross_brand THEN NULL ELSE sp.order_note END,
         sp.unit_weight_kg,
         CASE WHEN m.cross_brand OR m.price_null THEN NULL ELSE sp.supplier_sku END,
         CASE WHEN m.cross_brand THEN false ELSE sp.warehouse_pickup END,
         m.pos, sp.counts_toward_minimum, sp.case_unit, sp.units_per_case, 'SLONY', m.is_backup
    FROM gda_map m JOIN supplier_products sp ON sp.supplier_product_id = m.src_sp;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 130 THEN RAISE EXCEPTION 'catalog rows inserted: %', n; END IF;

  -- 4. settings: update template rows (old values stamped verbatim in notes), insert new rows
  UPDATE location_product_settings s
     SET min_stock_qty_base = v.mn, target_stock_qty_base = v.mx, max_stock_qty_base = v.mx,
         notes = s.notes || ' [2026-10-16 arkusz GDA, przed ' || s.min_stock_qty_base::text || '/'
                 || s.target_stock_qty_base::text || '/' || s.max_stock_qty_base::text || '; ' || v.stamp || ']'
    FROM gda_set v
   WHERE s.location_id = 'SLONY' AND s.product_id = v.product_id
     AND (s.min_stock_qty_base, s.target_stock_qty_base, s.max_stock_qty_base) IS DISTINCT FROM (v.mn, v.mx, v.mx);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 90 THEN RAISE EXCEPTION 'settings updated: expected 90, got %', n; END IF;

  INSERT INTO location_product_settings (setting_id, location_id, product_id, min_stock_qty_base,
         max_stock_qty_base, target_stock_qty_base, is_critical_for_location,
         allow_over_max_due_to_packaging, notes)
  SELECT 'SLONY__' || v.product_id, 'SLONY', v.product_id, v.mn, v.mx, v.mx, false, false,
         '2026-10-16 arkusz GDA (nowy wiersz); ' || v.stamp
    FROM gda_set v
   WHERE NOT EXISTS (SELECT 1 FROM location_product_settings s WHERE s.location_id = 'SLONY' AND s.product_id = v.product_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 18 THEN RAISE EXCEPTION 'settings inserted: expected 18, got %', n; END IF;

  -- post-checks -------------------------------------------------------------------------
  SELECT string_agg(e.supplier_id, ', ') INTO bad FROM (VALUES
      ('SUP_KUCHNIE_GDA', 7, 0),
      ('SUP_SELGROS_GDA', 30, 19),
      ('SUP_COCACOLA_GDA', 8, 0),
      ('SUP_WARSZAWA_GDA', 18, 0),
      ('SUP_BLUESERV_GDA', 48, 0)) e(supplier_id, n_primary, n_backup)
   WHERE (SELECT count(*) FROM supplier_products sp WHERE sp.supplier_id = e.supplier_id AND sp.location_id = 'SLONY'
           AND sp.active AND NOT sp.is_backup) <> e.n_primary
      OR (SELECT count(*) FROM supplier_products sp WHERE sp.supplier_id = e.supplier_id AND sp.location_id = 'SLONY'
           AND sp.active AND sp.is_backup) <> e.n_backup;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'per-supplier primary/backup counts wrong: %', bad; END IF;

  SELECT string_agg(b.supplier_product_id, ', ') INTO bad FROM supplier_products b
   WHERE b.location_id = 'SLONY' AND b.is_backup AND b.active
     AND NOT EXISTS (SELECT 1 FROM supplier_products p WHERE p.location_id = 'SLONY' AND p.product_id = b.product_id
                      AND p.active AND NOT p.is_backup);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'backup without primary: %', bad; END IF;

  SELECT string_agg(product_id, ', ') INTO bad FROM (
    SELECT product_id FROM supplier_products WHERE location_id = 'SLONY' AND active AND NOT is_backup
     GROUP BY product_id HAVING count(*) > 1) x;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'two primaries: %', bad; END IF;

  SELECT string_agg(supplier_id || '/' || product_id, ', ') INTO bad FROM (
    SELECT supplier_id, product_id FROM supplier_products WHERE location_id = 'SLONY' AND active
     GROUP BY supplier_id, product_id HAVING count(*) > 1) x;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'duplicate active (supplier, product): %', bad; END IF;

  SELECT string_agg(sp.supplier_product_id, ', ') INTO bad FROM supplier_products sp
   WHERE sp.location_id = 'SLONY'
     AND NOT EXISTS (SELECT 1 FROM location_product_settings s WHERE s.location_id = 'SLONY' AND s.product_id = sp.product_id);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'scoped rows without settings: %', bad; END IF;

  SELECT count(*) INTO n FROM supplier_products
   WHERE supplier_id IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA') AND (location_id IS DISTINCT FROM 'SLONY' OR NOT active);
  IF n <> 0 THEN RAISE EXCEPTION 'Gdańsk supplier rows outside SLONY or inactive: %', n; END IF;

  SELECT count(*) INTO n FROM location_product_settings
   WHERE location_id = 'SLONY' AND NOT (min_stock_qty_base <= target_stock_qty_base AND target_stock_qty_base <= max_stock_qty_base
                                       AND target_stock_qty_base = max_stock_qty_base);
  IF n <> 0 THEN RAISE EXCEPTION 'settings with min > target / target <> max: %', n; END IF;

  SELECT count(*) INTO n FROM location_product_settings WHERE location_id = 'SLONY';
  IF n <> 133 THEN RAISE EXCEPTION 'settings total: expected 133, got %', n; END IF;
  SELECT count(*) INTO n FROM location_product_settings WHERE location_id = 'SLONY' AND max_stock_qty_base > 0;
  IF n <> 101 THEN RAISE EXCEPTION 'settings with thresholds: expected 101, got %', n; END IF;

  fp_after := ARRAY[(SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id IS NULL),
                    (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id <> 'SLONY'),
                    (SELECT md5(string_agg(t::text, '|' ORDER BY t.setting_id)) FROM location_product_settings t WHERE t.location_id <> 'SLONY'),
                    (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_id)) FROM suppliers t WHERE t.supplier_id NOT IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA')),
                    (SELECT md5(string_agg(t::text, '|' ORDER BY t.location_id)) FROM locations t WHERE t.location_id <> 'SLONY')];
  IF fp_after IS DISTINCT FROM fp_before THEN
    RAISE EXCEPTION 'data outside SLONY changed: % -> %', fp_before, fp_after;
  END IF;

  IF dry_run THEN
    RAISE EXCEPTION 'DRY RUN OK: location 1, suppliers 5, catalog rows 130, settings updated 90 / inserted 18 / total 133 (101 with thresholds); nothing written';
  END IF;
  RETURN 'APPLIED: location 1, suppliers 5, catalog rows 130, settings updated 90 / inserted 18 / total 133';
END
$fn$;

SELECT public.gdansk_rollout_step1(true);   -- expect ERROR 'DRY RUN OK: …' (nothing written)
SELECT public.gdansk_rollout_step1(false);  -- the real run, returns 'APPLIED: …'
DROP FUNCTION public.gdansk_rollout_step1(boolean);

-- =====================================================================================
-- STEP 2 — audits (read-only). Expected result next to each query.
-- =====================================================================================
-- (a) suppliers — expect 5 rows, active, e-mail NULL; alerts off only for SUP_WARSZAWA_GDA
SELECT supplier_id, supplier_name, ordering_method, email, minimum_order_value_pln, nip, active,
       suggestion_alerts_enabled, coverage_prompt_enabled
  FROM suppliers WHERE supplier_id IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA') ORDER BY supplier_id;

-- (b) catalog per supplier — expect KUCHNIE 7+0, SELGROS 30+19, COCACOLA 8+0, WARSZAWA 18+0, BLUESERV 48+0 (primary+backup), all active
SELECT supplier_id, count(*) FILTER (WHERE NOT is_backup) AS primary_rows, count(*) FILTER (WHERE is_backup) AS backup_rows,
       count(*) FILTER (WHERE NOT active) AS inactive
  FROM supplier_products WHERE location_id = 'SLONY' GROUP BY supplier_id ORDER BY supplier_id;

-- (c) backups without an active primary at SLONY — expect 0 rows
SELECT b.supplier_product_id FROM supplier_products b
 WHERE b.location_id = 'SLONY' AND b.is_backup AND b.active
   AND NOT EXISTS (SELECT 1 FROM supplier_products p WHERE p.location_id = 'SLONY' AND p.product_id = b.product_id AND p.active AND NOT p.is_backup);

-- (d) scoped rows without settings — expect 0 rows
SELECT sp.supplier_product_id FROM supplier_products sp
 WHERE sp.location_id = 'SLONY'
   AND NOT EXISTS (SELECT 1 FROM location_product_settings s WHERE s.location_id = 'SLONY' AND s.product_id = sp.product_id);

-- (e) settings — expect total 133 before step 2 (121 after), 101 with thresholds, 0 bad
SELECT count(*) AS total, count(*) FILTER (WHERE max_stock_qty_base > 0) AS with_thresholds,
       count(*) FILTER (WHERE NOT (min_stock_qty_base <= target_stock_qty_base AND target_stock_qty_base = max_stock_qty_base)) AS bad
  FROM location_product_settings WHERE location_id = 'SLONY';

-- (f) captain view: tabs with orderable rows — expect 5 suppliers (KUCHNIE 7, SELGROS 49, COCACOLA 8, WARSZAWA 18, BLUESERV 48)
SELECT su.supplier_name, count(*) AS orderable
  FROM supplier_products sp
  JOIN suppliers su ON su.supplier_id = sp.supplier_id AND su.active
  JOIN products p ON p.product_id = sp.product_id AND p.active
  JOIN location_product_settings s ON s.location_id = 'SLONY' AND s.product_id = sp.product_id
 WHERE sp.location_id = 'SLONY' AND sp.active
 GROUP BY su.supplier_name ORDER BY 1;

-- (g) inventory list size (settings with an active product) — expect 132 before step 2 (P037 inactive), 121 after
SELECT count(*) FROM location_product_settings s JOIN products p USING (product_id) WHERE s.location_id = 'SLONY' AND p.active;

-- (h) location row — expect active, own_catalog, Chmielna 10, Pita Bros Gdańsk sp. z o.o., 5223329662
SELECT row_to_json(l) FROM locations l WHERE location_id = 'SLONY';

-- (i) fingerprints — expect identical to STEP 0e
SELECT 'shared_sp' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id IS NULL) AS md5;
SELECT 'other_scoped_sp' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_product_id)) FROM supplier_products t WHERE t.location_id <> 'SLONY') AS md5;
SELECT 'other_settings' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.setting_id)) FROM location_product_settings t WHERE t.location_id <> 'SLONY') AS md5;
SELECT 'other_suppliers' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.supplier_id)) FROM suppliers t WHERE t.supplier_id NOT IN ('SUP_KUCHNIE_GDA', 'SUP_SELGROS_GDA', 'SUP_COCACOLA_GDA', 'SUP_WARSZAWA_GDA', 'SUP_BLUESERV_GDA')) AS md5;
SELECT 'other_locations' AS part, (SELECT md5(string_agg(t::text, '|' ORDER BY t.location_id)) FROM locations t WHERE t.location_id <> 'SLONY') AS md5;
